/**
 * STAGE 13 (AUDIO) AUDIT PROBE — schedule level.
 *
 * Lane: audit-audio (stage 13 of the CROSSCHECK-PROTOCOL rebuild).
 * Owned area: data/audit/** — this file lives at data/audit/13/.
 *
 * WHAT IT MEASURES (AUD-01 re-approach, AUD-02, AUD-03, AUD-04 layer 1)
 *
 * Drives the REAL buildMgPackage()/buildSoundtrack() code (the same pure
 * modules render.js uses) over the same inputs the QA render suite uses
 * (qa-scripts/render-visual-tests.sh: ch-01 finance fixture, ch-48 process
 * fixture, ch-02 legal REAL gate-passed script), each with a fixture SRT
 * generated by the SAME tool the QA shell uses (make-fixture-srt.mjs) and
 * the channel config render.js would pass (sfx_profile.silence_technique,
 * script_template.reveal_placement, icon_map). Plus the real synced
 * movile-cave SRT pair, mirroring verify-compositions.js's call.
 *
 * A render-level check (mixed audio in the finished MP4) is deliberately
 * NOT attempted here: this machine has no @remotion/renderer, no
 * compositor, no real VO audio (EdgeTTS needs a WebSocket the sandbox
 * proxy does not carry), and no rendered MP4 on disk. That limitation is
 * recorded in the ledger as the reason AUD-07/AUD-08 and the mix-level
 * half of AUD-04 stay UNVERIFIABLE here.
 *
 * METRICS EMITTED PER INPUT
 *   beats, usedAuthoredBeats, synthesized
 *   soundtrack.length (after global thinning + silence suppression)
 *   events-per-beat: distribution, max, count of beats with > 1 event
 *   AUD-03 classification per event: STATE_START (visual-land),
 *     TEXTURE_TICK (repeat state by design) or OTHER (defect)
 *   AUD-04 layer 1: expected volume/targetDb recomputed from the library
 *     and the ROLE_TARGET_DB table; violations reported
 *   resolve-locally: every event file exists under public/
 *   visual.sound summary (the same numbers that ship in *-visual-report.json)
 *
 * Run:  node data/audit/13/probe-audio-schedule.mjs
 */
import { readFileSync, existsSync } from "fs";
import { join, dirname } from "path";
import { fileURLToPath, pathToFileURL } from "url";
import { execFileSync } from "child_process";
import { narrationSections } from "../../../src/utils/script-narration.js";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, "..", "..", "..");
const R = join(ROOT, "src", "skills", "remotion-render");

const mgp = await import(pathToFileURL(join(R, "compositions", "mg-package.js")).href);
const { buildMgPackage } = mgp;
const sound = await import(pathToFileURL(join(R, "visual", "sound-design.js")).href);
const { MAX_EVENTS_PER_BEAT, MIN_GAP_FRAMES, ROLE_TARGET_DB, volumeFor, STATE_SOUND_MAP } = sound;
const sfxLib = await import(pathToFileURL(join(R, "visual", "sfx-library.js")).href);
const { SFX_LIBRARY } = sfxLib;

const FPS = 30;

function loadJson(p) {
  return JSON.parse(readFileSync(p, "utf-8"));
}

const channelsJson = loadJson(join(ROOT, "config", "channels.json"));
const channels = Array.isArray(channelsJson.channels) ? channelsJson.channels : channelsJson;
// channels.json keys a channel by `channel_id` ("ch-01") AND numeric `id`
// (1); the QA shell addresses them by the numeric id. Match both.
const channelFor = (id) => channels.find((c) => String(c.channel_id) === `ch-${String(id).padStart(2, "0")}` || String(c.id) === String(id));

/** Replicate render.js's SRT discovery + the QA shell's totalMs derivation. */
function fixtureSrt(scriptPath, outName) {
  // make-fixture-srt.mjs refuses non-.fixture.srt outputs on purpose: a
  // fixture SRT must never be mistaken for real TTS sync. Follow the QA
  // shell's pattern (write .fixture.srt, then read that text).
  const out = join(HERE, `${outName}.fixture.srt`);
  execFileSync("node", [join(R, "qa-scripts", "make-fixture-srt.mjs"), scriptPath, out], { stdio: "ignore" });
  const srt = readFileSync(out, "utf-8");
  // Last cue end + 1s — the exact math render-visual-tests.sh does for the
  // silent placeholder mp3 it hands render.js.
  const last = [...srt.matchAll(/--> (\d+):(\d+):(\d+),(\d+)/g)].pop();
  const secs = Number(last[1]) * 3600 + Number(last[2]) * 60 + Number(last[3]) + Number(last[4]) / 1000 + 1;
  return { srt, totalMs: Math.round(secs * 1000) };
}

function classify(beat, ev) {
  const state = (beat.visualStates || []).find((s) => s.key === ev.state);
  if (!state) return { cls: "OTHER", note: `state "${ev.state}" not found in beat's visualStates` };
  const spec = STATE_SOUND_MAP[beat.visualPlan && beat.visualPlan.strategy]?.[state.key];
  const repeat = !!(spec && spec.repeat);
  // AUD-03: does the event sit on the visual state's START frame
  // (visual-land), or drift onto narration word timing?
  const localDelta = ev.localFrame - state.startFrame;
  if (repeat) return { cls: "TEXTURE_TICK", note: `repeat state "${state.key}" by design`, localDelta };
  if (ev.localFrame === state.startFrame) return { cls: "STATE_START", note: `visual-land: state "${state.key}" startFrame ${state.startFrame}`, localDelta: 0 };
  return { cls: "OTHER", note: `localFrame ${ev.localFrame} != state.startFrame ${state.startFrame}`, localDelta };
}

function analyze(input) {
  const { name, srt, opts } = input;
  const mg = buildMgPackage(srt, opts);

  // events-per-beat via absolute-frame range membership
  const events = mg.soundtrack || [];
  const perBeat = mg.beats.map((b) => {
    const lo = b.startFrame;
    const hi = b.startFrame + b.durationInFrames;
    return events.filter((e) => e.atFrame >= lo && e.atFrame < hi);
  });
  const maxInBeat = Math.max(0, ...perBeat.map((l) => l.length));
  const beatsOverOne = perBeat.filter((l) => l.length > 1).length;

  const classification = {
    STATE_START: 0,
    TEXTURE_TICK: 0,
    OTHER: [],
  };
  const anchorCheck = [];
  for (let i = 0; i < mg.beats.length; i++) {
    for (const ev of perBeat[i]) {
      const r = classify(mg.beats[i], ev);
      if (r.cls === "STATE_START" || r.cls === "TEXTURE_TICK") classification[r.cls]++;
      else classification.OTHER.push({ atFrame: ev.atFrame, state: ev.state, note: r.note });
      // AUD-03 evidence: where does the event sit relative to its beat
      // anchor and its beat's own visual state start?
      anchorCheck.push({
        atFrame: ev.atFrame,
        beatAnchorFrame: mg.beats[i].anchorFrame,
        deltaFromAnchor: ev.atFrame - mg.beats[i].anchorFrame,
        state: ev.state,
        cls: r.cls,
        localDelta: r.localDelta,
      });
    }
  }

  // AUD-04 layer 1: recompute expected volume/targetDb from the same inputs
  const volViolations = [];
  const targetViolations = [];
  const missingFiles = [];
  for (const ev of events) {
    const expectedTarget = ROLE_TARGET_DB[ev.role] ?? -26;
    if (ev.targetDb !== expectedTarget) targetViolations.push({ atFrame: ev.atFrame, role: ev.role, targetDb: ev.targetDb, expectedTarget });
    if (ev.volume > 1) volViolations.push({ atFrame: ev.atFrame, role: ev.role, volume: ev.volume, note: "boost above unity" });
    const lib = SFX_LIBRARY.find((e) => e.file === ev.file);
    if (lib) {
      const expectedVolume = volumeFor(lib, ev.role);
      if (Math.abs(expectedVolume - ev.volume) > 0.001) {
        volViolations.push({ atFrame: ev.atFrame, role: ev.role, volume: ev.volume, expectedVolume, file: ev.file });
      }
    } else if (!ev.file) {
      // no asset — event exists but plays silence; note, not a violation
    } else {
      volViolations.push({ atFrame: ev.atFrame, file: ev.file, note: "NOT in SFX_LIBRARY" });
    }
    const p = join(R, "public", ev.file);
    if (ev.file && !existsSync(p)) missingFiles.push(ev.file);
  }

  return {
    name,
    beats: mg.beats.length,
    usedAuthoredBeats: mg.usedAuthoredBeats,
    synthesized: mg.synthesized,
    events: events.length,
    soundSuppressedBySilence: mg.soundSuppressedBySilence,
    silenceWindow: mg.silenceWindow,
    eventsPerBeat: perBeat.map((l) => l.length),
    maxEventsInBeat: maxInBeat,
    beatsWithMoreThanOneEvent: beatsOverOne,
    exceedsOnePerBeatSpec: maxInBeat > 1,
    classification,
    anchorCheck,
    volViolations,
    targetViolations,
    missingFiles,
    soundSummary: mg.visual ? mg.visual.sound : null,
    specs: { MAX_EVENTS_PER_BEAT, MIN_GAP_FRAMES },
  };
}

const fixtures = join(R, "qa-scripts", "fixtures");
const inputs = [];

for (const [id, scriptRel, name] of [
  [1, join(fixtures, "finance-accumulation.fixture.json"), "ch-01 finance-accumulation (fixture)"],
  [48, join(fixtures, "tech-process.fixture.json"), "ch-48 tech-process (fixture)"],
  [2, join(ROOT, "data", "research", "2", "google-location-history-chatrie-ruling-shorts-script.json"), "ch-02 chatrie ruling (REAL script)"],
]) {
  const script = loadJson(scriptRel);
  const ch = channelFor(id);
  const { srt, totalMs } = fixtureSrt(scriptRel, `${name.split(" ")[1]}-audit`);
  // render.js applies narrationSections() BEFORE buildMgPackage (fold the
  // top-level hook into section one so TTS and the timing model agree);
  // make-fixture-srt.mjs folds identically, so both sides must use the
  // folded sections for the word-count gate to pass.
  const narr = narrationSections(script);
  inputs.push({
    name,
    srt,
    opts: {
      fps: FPS,
      sections: narr.filter((s) => s.voiceover && s.voiceover.trim()),
      hook: script.hook || null,
      channel: ch || null,
      iconMap: (ch && ch.icon_map) || null,
      bRollFiles: [],
      imageForSection: () => null,
      totalMs,
      revealPlacement: ch && ch.script_template && ch.script_template.reveal_placement,
      silenceTechnique: ch && ch.sfx_profile && ch.sfx_profile.silence_technique,
    },
  });
}

// Real synced SRT case, mirroring verify-compositions.js's call exactly.
{
  const script = loadJson(join(ROOT, "data", "scripts", "ch-fixture", "movile-cave-shorts-script.json"));
  const sections = narrationSections(script)
    .filter((s) => s.voiceover && s.voiceover.trim())
    .map((s) => ({ id: s.id, timing: s.timing, voiceover: s.voiceover }));
  const mgChannel = channels.find((c) => c.style === "motion-graphics");
  inputs.push({
    name: "ch-fixture movile-cave + REAL synced SRT (verify-compositions call shape)",
    srt: readFileSync(join(ROOT, "data", "tts", "ch-fixture", "movile-cave-shorts-script-vo.srt"), "utf-8"),
    opts: { fps: FPS, sections, iconMap: (mgChannel && mgChannel.icon_map) || null, bRollFiles: [], imageForSection: () => null },
  });
}

const results = inputs.map(analyze);
console.log(JSON.stringify(results, null, 2));